def fix(self):
    """Return a version of the source code with PEP 8 violations fixed."""
    pep8_options = {
        'ignore': self.options.ignore,
        'select': self.options.select,
        'max_line_length': self.options.max_line_length,
        'hang_closing': self.options.hang_closing,
